<?php
/**
 * Application configuration (defaults for a local computer).
 *
 * LIVE SERVER: do not edit this file there — a Git deployment would overwrite it.
 * Put the server's values in config/config.local.php instead (not in git, never
 * overwritten). It only needs the values that differ, for example:
 *
 *   <?php
 *   return ['db' => ['name' => 'u123456789_agency', 'user' => 'u123456789_agency', 'pass' => '...']];
 *
 * hPanel > Databases > MySQL Databases shows the database name, user and password.
 */
$config = [
    'db' => [
        'host'    => 'localhost',
        'port'    => 3306,
        'name'    => 'security_agency',
        'user'    => 'root',
        'pass'    => 'root123',
        'charset' => 'utf8mb4',
    ],

    'app' => [
        // Shown before the company name is set in Admin > Settings.
        'name'     => 'Security Agency',
        'timezone' => 'Asia/Kolkata',

        // Leave empty to auto-detect. Set e.g. 'https://example.com' or
        // 'https://example.com/agency' if auto-detection is wrong.
        'base_url' => '',

        // Set true only while debugging. Never leave true on a live site.
        'debug'    => false,
    ],
];

$local = __DIR__ . '/config.local.php';
return is_file($local) ? array_replace_recursive($config, require $local) : $config;
